for (var g=3.5; g<=3.8; g+=0.1){
  svg.appendChild(el("line",{x1:margin.left, x2:margin.left+PW, y1:yp(g), y2:yp(g), stroke:"#ececec","stroke-width":"0.5"}));
}

// event marker: Aug 21 two-year plus high (index 18)
var evX = xp(18);
svg.appendChild(el("line",{x1:evX, x2:evX, y1:margin.top, y2:margin.top+PH, stroke:"#1a3560", "stroke-opacity":"0.5","stroke-dasharray":"2,3"}));
svg.appendChild(el("text",{x:evX-3, y:margin.top+12, "text-anchor":"end","font-size":"7","font-weight":"700",fill:"#1a3560","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "SOMMET DE 26 MOIS"));

