  d += (i===0?"M":"L") + xp(i) + "," + yp(data[i]) + " ";
}
svg.appendChild(el("path",{d:d, fill:"none", stroke:"#4a5568","stroke-width":"1.6"}));

svg.appendChild(el("line",{x1:margin.left, x2:margin.left+PW, y1:margin.top+PH, y2:margin.top+PH, stroke:"#d8d8d8","stroke-width":"1"}));

var lastX = xp(n-1), lastY = yp(data[n-1]);
svg.appendChild(el("circle",{cx:lastX, cy:lastY, r:4, fill:"#4a5568"}));

[3.5,3.6,3.7,3.8].forEach(function(v){
  svg.appendChild(el("text",{x:margin.left-6, y:yp(v)+3, "text-anchor":"end","font-size":"8.5",fill:"#aaaaaa","font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, v.toFixed(1).replace(".", ",")+"\u00a0%"));
